from functools import lru_cache
@lru_cache(None)
def f(n):
    return 0 if n == 0 else 1 if n == 1 else f(n - 1) + f(n - 2)
n = int(input())
print(f(n))

from functools import lru_cache
@lru_cache(None)
def f(n):
    return 0 if n==0 else 2*f(n-1)+1
n=int(input())
print(f(n))

from functools import lru_cache
@lru_cache(None)
def f(n):
    return 2 if n==0 else f(n-1)+n
n=int(input())
print(f(n))

n=int(input())
a=[list(map(int,input().split())) for _ in range(n)]
lo=[[10**9]*n for _ in range(n)]
hi=[[-10**9]*n for _ in range(n)]
lo[0][0]=hi[0][0]=2*a[0][0]
for i in range(n):
    for j in range(n):
        if i==0 and j==0: continue
        vals=[]
        if i: vals.append((lo[i-1][j],hi[i-1][j],a[i][j]))
        if j: vals.append((lo[i][j-1],hi[i][j-1],a[i][j]))
        if i and j: vals.append((lo[i-1][j-1],hi[i-1][j-1],2*a[i][j]))
        lo[i][j]=min(x[0]+x[2] for x in vals);hi[i][j]=max(x[1]+x[2] for x in vals)
hi[-1][-1]+=a[-1][-1];lo[-1][-1]+=a[-1][-1]
print(hi[-1][-1],lo[-1][-1])

